use std::{env, fs, io::Write, path::Path};
fn main() {
    let args: Vec<String> = env::args().collect();
    let root = Path::new(&args[1]);
    let out = Path::new(&args[2]);
    fs::create_dir_all(out).unwrap();
    let mut inputs: Vec<_> = fs::read_dir(root).unwrap().map(|p| p.unwrap().path()).filter(|p| matches!(p.extension().and_then(|e| e.to_str()), Some("adts"|"m4a"|"mp4"|"latm"|"loas"|"m4s"))).collect();
    inputs.sort();
    for p in inputs {
        let data = fs::read(&p).unwrap();
        let mut file = fs::File::create(out.join(p.file_name().unwrap())).unwrap();
        match syom::decode_with(&data, &syom::DecodeOptions::unbounded()) {
            Ok(audio) => {
                file.write_all(b"PCM").unwrap();
                file.write_all(&audio.sample_rate.to_le_bytes()).unwrap();
                file.write_all(&(audio.channels.len() as u64).to_le_bytes()).unwrap();
                for plane in audio.channels {
                    file.write_all(&(plane.len() as u64).to_le_bytes()).unwrap();
                    for x in plane { file.write_all(&x.to_bits().to_le_bytes()).unwrap(); }
                }
            }
            Err(e) => write!(file,"ERR:{e:?}").unwrap(),
        }
    }
}
